 root.querySelectorAll('[data-receipt]').forEach(b=>b.onclick=()=>{const inp=document.createElement('input');inp.type='file';inp.accept='.pdf,.jpg,.png';inp.onchange=async()=>{if(!inp.files[0])return;try{await hupload(`/hrm/reimbursements/${b.dataset.receipt}/receipt`,inp.files[0]);toast('Receipt uploaded privately')}catch(e){toast(e.message,'error')}};inp.click()});
 root.querySelectorAll('[data-reimb]').forEach(b=>b.onclick=async()=>{try{await hsave(`/hrm/reimbursements/${b.dataset.reimb}/review`,'PATCH',{decision:b.dataset.decision});toast('Claim reviewed');hrmReimbursements(root)}catch(e){toast(e.message,'error')}});
